{
  "items": [
    {
      "index": 1,
      "combo": "A",
      "scene": "公共交通出行",
      "angle": "已知总人数和每车限乘人数，笔算求需几辆车及余数，并用乘法验算结果。",
      "roles": {
        "两、三位数除以一位数的笔算方法": "计算商和余数，确定车辆数和剩余人数",
        "除法的验算方法": "通过“商×除数+余数”验证计算结果是否等于总人数"
      }
    },
    {
      "index": 2,
      "combo": "A",
      "scene": "校园活动组织",
      "angle": "先算出分组后的总人数，再从全校总人数中减去该组人数，求其他年级人数。",
      "roles": {
        "乘除法与加减法两步混合运算（无括号）": "构建“总数-每组人数×组数”的算式结构",
        "三位数减法竖式（退位）": "执行最后的减法步骤，处理连续退位计算"
      }
    },
    {
      "index": 3,
      "combo": "A",
      "scene": "公平游戏与概率",
      "angle": "将不同游戏的积分转换为元角分形式的小数，并比较这些小数的大小决定胜负。",
      "roles": {
        "结合元角分认识小数": "将整数积分或简单换算值理解为带有两位小数的金额形式",
        "万以内数比较大小": "依据小数比较规则（先比整数部分再比小数部分）判断高低"
      }
    },
    {
      "index": 4,
      "combo": "A",
      "scene": "科学实验与测量",
      "angle": "读取以毫米为单位的植物生长数据，将其改写成以分米为单位的小数并进行记录。",
      "roles": {
        "毫米和分米的认识": "理解1分米=100毫米的进率关系",
        "结合米制单位认识小数": "将毫米数值除以100，正确写出两位小数表示的分米数"
      }
    },
    {
      "index": 5,
      "combo": "A",
      "scene": "体育比赛计分",
      "angle": "根据总分和平均分反推参赛场次，重点处理商中间或末尾有0的乘法验算过程。",
      "roles": {
        "除法的验算方法": "利用乘法逆向验证除法结果的正确性",
        "0和乘法竖式中0的处理": "在验算乘法时，正确处理因数中间或末尾有0的情况"
      }
    },
    {
      "index": 6,
      "combo": "A",
      "scene": "动物观察与保护",
      "angle": "计算几种动物的寿命总和与另一种动物寿命的差值，涉及进位加法和混合运算顺序。",
      "roles": {
        "乘除法与加减法两步混合运算（无括号）": "确定先算乘法（如倍数关系）再加减的运算顺序",
        "三位数加法竖式（进位）": "在执行加法步骤时，准确处理满十进一的计算"
      }
    }
  ]
}
